using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
partial class VectorShape {
 public Dictionary<int,PointF[]> Handles=new Dictionary<int,PointF[]>();
 public bool HasPointHandles {get{return Kind!="Compound"&&Kind!="Text"&&Points.Count>=2;}}
 bool ClosedHandles {get{return Kind=="Ellipse"||Kind=="Polygon"||Kind=="Closed curve";}}
 public PointF[] PointHandles(int index){if(Kind=="Ellipse")return EllipsePointHandles(index);PointF[] value;if(Handles.TryGetValue(index,out value))return value;var p=Points[index];var prev=Points[index==0?(ClosedHandles?Points.Count-1:0):index-1];var next=Points[index==Points.Count-1?(ClosedHandles?0:index):index+1];if(Kind=="Curvature pen"||Kind=="Closed curve"){float factor=(Kind=="Closed curve"?.5522848f:.5f)/3;var t=new PointF((next.X-prev.X)*factor,(next.Y-prev.Y)*factor);return new[]{new PointF(-t.X,-t.Y),t};}return new[]{new PointF((prev.X-p.X)/3,(prev.Y-p.Y)/3),new PointF((next.X-p.X)/3,(next.Y-p.Y)/3)};}
 public PointF HandlePosition(int index,int side){var p=Grips()[index];var h=PointHandles(index)[side];return new PointF(p.X+h.X,p.Y+h.Y);}
 public bool HandleVisible(int index,int side){return ClosedHandles||side==0&&index>0||side==1&&index<Points.Count-1;}
 public void SetPointHandle(int index,int side,PointF position,bool breakAlignment=false){var h=(PointF[])PointHandles(index).Clone();var p=Points[index];double cross=(double)h[0].X*h[1].Y-(double)h[0].Y*h[1].X,dot=(double)h[0].X*h[1].X+(double)h[0].Y*h[1].Y;bool aligned=Math.Abs(cross)<=.0001*Math.Max(1,StrokeSession.Distance(PointF.Empty,h[0])*StrokeSession.Distance(PointF.Empty,h[1]))&&dot<=0;h[side]=new PointF(position.X-p.X,position.Y-p.Y);int other=1-side;double length=StrokeSession.Distance(PointF.Empty,h[side]),opposite=StrokeSession.Distance(PointF.Empty,h[other]);if(!breakAlignment&&aligned&&length>.0001&&HandleVisible(index,other)){if(opposite<.0001)opposite=length;h[other]=new PointF((float)(-h[side].X*opposite/length),(float)(-h[side].Y*opposite/length));}Handles[index]=h;}
 public GraphicsPath HandlePath(){var path=new GraphicsPath();int count=ClosedHandles?Points.Count:Points.Count-1;for(int i=0;i<count;i++){int next=(i+1)%Points.Count;path.AddBezier(Points[i],HandlePosition(i,1),HandlePosition(next,0),Points[next]);}if(ClosedHandles)path.CloseFigure();return path;}
 public Dictionary<int,PointF[]> CopyHandles(){return Handles.ToDictionary(k=>k.Key,k=>(PointF[])k.Value.Clone());}
 public void TransformHandles(Matrix matrix){foreach(var value in Handles.Values)matrix.TransformVectors(value);}
 public void ShiftHandleIndices(int index,bool insert){var next=new Dictionary<int,PointF[]>();foreach(var entry in Handles){if(!insert&&entry.Key==index)continue;next[entry.Key>=index?entry.Key+(insert?1:-1):entry.Key]=entry.Value;}Handles=next;}
 public void WriteHandles(BinaryWriter w){w.Write(Handles.Count);foreach(var entry in Handles){w.Write(entry.Key);foreach(var p in entry.Value){w.Write(p.X);w.Write(p.Y);}}}
 public void ReadHandles(BinaryReader r){int count=r.ReadInt32();if(count<0||count>Points.Count)throw new InvalidDataException("Invalid vector handles");for(int i=0;i<count;i++){int index=r.ReadInt32();if(index<0||index>=Points.Count||Handles.ContainsKey(index))throw new InvalidDataException("Invalid handle point");var pts=new PointF[2];for(int j=0;j<2;j++){float x=r.ReadSingle(),y=r.ReadSingle();if(float.IsNaN(x)||float.IsNaN(y)||Math.Abs(x)>200000||Math.Abs(y)>200000)throw new InvalidDataException("Invalid handle coordinates");pts[j]=new PointF(x,y);}Handles[index]=pts;}}
}
partial class Canvas {
 int curveHandlePoint=-1,curveHandleSide;
 bool PickPointHandle(PointF p){if(selectedVector==null||selectedPaths.Count!=1||!selectedVector.HasPointHandles)return false;foreach(int index in selectedPoints)for(int side=0;side<2;side++)if(selectedVector.HandleVisible(index,side)&&StrokeSession.Distance(p,selectedVector.HandlePosition(index,side))*Zoom<8){curveHandlePoint=index;curveHandleSide=side;vectorHandle=-4;StartVectorDrag(p);return true;}return false;}
 void PaintPointHandles(Graphics g){if(selectedVector==null||!selectedVector.HasPointHandles)return;using(var pen=new Pen(Color.Teal,1/Zoom))foreach(int index in selectedPoints){if(index>=selectedVector.Grips().Length)continue;for(int side=0;side<2;side++){if(!selectedVector.HandleVisible(index,side))continue;var p=selectedVector.HandlePosition(index,side);g.DrawLine(pen,selectedVector.Grips()[index],p);g.FillEllipse(Brushes.White,p.X-4/Zoom,p.Y-4/Zoom,8/Zoom,8/Zoom);g.DrawEllipse(pen,p.X-4/Zoom,p.Y-4/Zoom,8/Zoom,8/Zoom);}}}
 public void TestPointHandles(){var shape=Doc.Selected.Vectors.Last();ClearSelectedPaths();AddSelectedPath(shape);selectedVector=shape;SelectVectorPoint(0,false);var start=shape.HandlePosition(0,1);var end=new PointF(start.X,start.Y-45);if(!PickPointHandle(start))throw new Exception("Handle hit");VectorMove(end);VectorUp(end);if(StrokeSession.Distance(shape.HandlePosition(0,1),end)>.01)throw new Exception("Handle drag");TestDraftPaint();}
}
partial class Studio {
 public void PreviewVectorHandles(){SetDocument(new Document("A3",150),null);AddTypedLayer(true);canvas.Zoom=1;canvas.Offset=PointF.Empty;vectorMode.SelectedItem="Line";canvas.TestDrag(new Point(400,300),new Point(1000,400));vectorPicker.PerformClick();canvas.TestPointHandles();canvas.Fit();using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"vector-handles-preview.png"));}dirty=false;}
 public void TestVersion31(){using(var layer=new Layer("test",200,200)){layer.Adjustment=new LayerAdjustment{Hue=75,Saturation=30,Brightness=15};using(var g=Graphics.FromImage(layer.Image))g.Clear(Color.Blue);layer.Rendered();using(var g=Graphics.FromImage(layer.Image)){g.CompositingMode=CompositingMode.SourceCopy;g.FillRectangle(new SolidBrush(Color.FromArgb(90,200,80,20)),40,50,30,40);}layer.UpdatePixelAdjustment(new Rectangle(40,50,30,40));var patched=Document.Png(layer.Rendered());layer.InvalidateAdjustment();if(!patched.SequenceEqual(Document.Png(layer.Rendered())))throw new Exception("Adjustment patch output");}SetDocument(new Document("A4",100),null);canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.Doc.Selected.Adjustment=new LayerAdjustment{Brightness=15,Hue=90};canvas.Doc.Selected.Rendered();SelectTool("Pen");canvas.TestDrag(new Point(80,100),new Point(280,100));var cached=Document.Png(canvas.Doc.Selected.Rendered());canvas.Doc.Selected.InvalidateAdjustment();if(!cached.SequenceEqual(Document.Png(canvas.Doc.Selected.Rendered())))throw new Exception("Adjusted stroke finish cache");AddTypedLayer(true);canvas.Zoom=1;canvas.Offset=PointF.Empty;vectorMode.SelectedItem="Line";canvas.TestDrag(new Point(100,200),new Point(300,200));vectorPicker.PerformClick();canvas.TestPointHandles();var shape=canvas.Doc.Selected.Vectors.Last();using(var path=shape.Path())if(path.GetBounds().Top>=199)throw new Exception("Handle bends line");Travel(undo,redo);if(canvas.Doc.Selected.Vectors.Last().Handles.Count!=0)throw new Exception("Handle undo");Travel(redo,undo);shape=canvas.Doc.Selected.Vectors.Last();var offset=shape.PointHandles(0)[1];shape.Rotate(90);if(Math.Abs(shape.PointHandles(0)[1].X+offset.Y)>.01)throw new Exception("Rotate handles");string file=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(file);using(var loaded=Document.Load(file))if(loaded.Selected.Vectors.Last().Handles.Count!=1)throw new Exception("Handle persistence");}finally{if(File.Exists(file))File.Delete(file);}dirty=false;}
}
}
